public class ClassAttendanceTracker { static int[] attendanceSummary(int[] days){int present=0,streak=0,longest=0;for(int day:days){if(day==1){present++;streak++;longest=Math.max(longest,streak);}else streak=0;}return new int[]{present,longest};} public static void main(String[]args){int[] result=attendanceSummary(new int[]{1,1,0,1,1,1,0,1});System.out.println("Present: "+result[0]+", Longest streak: "+result[1]);} }
